// =========================================================================
// 🧭 ROUTE & PARSE INCOMING TELEGRAM EVENT (Text, Voice, or Callback Query)
// =========================================================================
const input = $input.first()?.json || {};
const DEFAULT_CHAT_ID = "1519369571"; // Serhat Kumas Telegram Chat ID

// Access workflow persistent memory
const staticData = $getWorkflowStaticData("global");
staticData.sessions = staticData.sessions || {};
staticData.processedUpdates = staticData.processedUpdates || {};

// Critical: Strip any heavy base64 image strings from staticData so n8n task runner stays featherlight (<5KB)
if (staticData.images) {
  delete staticData.images;
}
// Also cap __images cache at 20 entries
if (staticData.__images) { delete staticData.__images; }
if (staticData.sessions) {
  for (const s of Object.values(staticData.sessions)) {
    if (s.currentDraft?.carouselSlides) {
      s.currentDraft.carouselSlides.forEach(slide => { delete slide.base64; });
    }
  }
}
if (staticData.lastDraft?.carouselSlides) {
  staticData.lastDraft.carouselSlides.forEach(slide => { delete slide.base64; });
}

// Clean up old processed updates (older than 3 min) AND cap at 30 entries
const now = Date.now();
for (const [key, timestamp] of Object.entries(staticData.processedUpdates)) {
  if (now - timestamp > 180000) {
    delete staticData.processedUpdates[key];
  }
}
// Hard cap: keep only 30 most recent entries to prevent unbounded growth
const puKeys = Object.keys(staticData.processedUpdates);
if (puKeys.length > 30) {
  const sorted = puKeys.sort((a, b) => staticData.processedUpdates[a] - staticData.processedUpdates[b]);
  sorted.slice(0, puKeys.length - 30).forEach(k => delete staticData.processedUpdates[k]);
}

// 1. Thorough Callback Query Detection (handles callback_query, query, callbackQuery, and unwrapped updates)
const cq = input.callback_query || 
           input.query || 
           input.callbackQuery || 
           input.body?.callback_query || 
           input.update?.callback_query || 
           (input.data !== undefined && (input.id !== undefined || input.from !== undefined) ? input : null);

if (cq || input.data !== undefined) {
  const actualCq = cq || input;
  const callbackId = actualCq.id || actualCq.query_id || input.id || "cb_" + Date.now();
  const callbackData = String(actualCq.data || input.data || "").trim();
  const chatId = String(actualCq.message?.chat?.id || actualCq.from?.id || input.message?.chat?.id || input.from?.id || DEFAULT_CHAT_ID);
  const messageId = actualCq.message?.message_id || input.message?.message_id;
  const userSession = staticData.sessions[chatId] || { state: "idle" };

  // Deduplicate callback clicks
  const cbKey = "cb_" + chatId + "_" + callbackId;
  if (staticData.processedUpdates[cbKey]) {
    return [{ json: { eventType: "ignored", reason: "duplicate_callback", chatId } }];
  }
  staticData.processedUpdates[cbKey] = now;

  const messageText = actualCq.message?.text || input.message?.text || "";
  const messageCaption = actualCq.message?.caption || input.message?.caption || "";
  const messageEntities = actualCq.message?.entities || actualCq.message?.caption_entities || input.message?.entities || [];

  return [{
    json: {
      eventType: "callback",
      callbackId,
      callbackData,
      chatId,
      messageId,
      userSession,
      messageText,
      messageCaption,
      messageEntities,
      timestamp: new Date().toISOString()
    }
  }];
}

// 2. Handle Message (Voice Note or Regular Text)
const msg = input.message || input.msg || input;
const chatId = String(msg.chat?.id || msg.from?.id || input.from?.id || DEFAULT_CHAT_ID);
const messageId = msg.message_id || input.message_id;
const updateId = input.update_id || (messageId ? (chatId + "_" + messageId) : null);
const userSession = staticData.sessions[chatId] || { state: "idle" };

// 2.0 Deduplication Guard: Ignore if exact same update / message was already processed
if (updateId) {
  const uKey = "msg_" + updateId;
  if (staticData.processedUpdates[uKey]) {
    return [{ json: { eventType: "ignored", reason: "duplicate_update", chatId } }];
  }
  staticData.processedUpdates[uKey] = now;
}

// 2a. Voice Note / Audio Message
const voiceObj = msg.voice || msg.audio || input.voice || input.audio;
if (voiceObj) {
  return [{
    json: {
      eventType: "voice",
      fileId: voiceObj.file_id,
      duration: voiceObj.duration,
      mimeType: voiceObj.mime_type || "audio/ogg",
      chatId,
      messageId,
      userSession,
      timestamp: new Date().toISOString()
    }
  }];
}

// 2b. Regular Text Message - ONLY IF text is non-empty!
const rawText = String(msg.text || input.text || "").trim();
if (rawText.length > 0) {
  // Debounce identical text from same user within 4 seconds (prevents rapid multi-queue triggers)
  const textHash = "txt_" + chatId + "_" + rawText.slice(0, 60);
  if (staticData.processedUpdates[textHash] && (now - staticData.processedUpdates[textHash] < 4000)) {
    return [{ json: { eventType: "ignored", reason: "debounced_duplicate_text", chatId } }];
  }
  staticData.processedUpdates[textHash] = now;

  return [{
    json: {
      eventType: "text",
      rawText,
      chatId,
      messageId,
      userSession,
      timestamp: new Date().toISOString()
    }
  }];
}

// 2c. Unrecognized or empty update - never default to text!
return [{
  json: {
    eventType: "ignored",
    chatId,
    timestamp: new Date().toISOString()
  }
}];

// Prepare voice audio buffer for Gemini 3.5 Flash Lite multimodal input
const items = $input.all();
const output = [];

for (let i = 0; i < items.length; i++) {
  const item = items[i];
  if (!item.binary?.data) {
    throw new Error('No audio binary found in "data". Voice download may have failed.');
  }

  const buffer = await this.helpers.getBinaryDataBuffer(i, 'data');
  if (!buffer.length) {
    throw new Error('Downloaded audio is empty. Try sending voice message again.');
  }

  const meta = $('Route & Parse Event').first().json;

  output.push({
    json: {
      chatId: meta.chatId,
      audioMimeType: item.binary.data.mimeType || 'audio/ogg',
      audioBase64: buffer.toString('base64'),
      userSession: meta.userSession
    },
    pairedItem: { item: i }
  });
}

return output;

