// Extract transcription text and convert to standardized text payload
const resp = $input.first()?.json || {};
const audioMeta = $('Prepare Voice Audio').first().json;

const text = resp.candidates?.[0]?.content?.parts?.[0]?.text?.trim() || '';
if (!text) {
  throw new Error('Gemini could not transcribe audio or speech was silent. Please try again or type text.');
}

return [{
  json: {
    eventType: 'text',
    rawText: text,
    chatId: audioMeta.chatId,
    isFromVoice: true,
    userSession: audioMeta.userSession,
    timestamp: new Date().toISOString()
  }
}];

// =========================================================================
// 🧠 INTENT, FORMAT & SESSION EVALUATOR  (v2 – task-runner safe)
// =========================================================================
const item = $input.first()?.json || {};
const text = String(item.rawText || "").trim();
const chatId = String(item.chatId);
const isFromVoice = Boolean(item.isFromVoice);

// Guard against empty / spurious triggers
if (!text) {
  return [];
}

// ── Lightweight staticData access with self-healing size guard ──────────
const staticData = $getWorkflowStaticData("global");
staticData.sessions = staticData.sessions || {};
staticData.processedUpdates = staticData.processedUpdates || {};

// SAFETY: If staticData has become too large, nuke it to prevent runner crash
try {
  const blob = JSON.stringify(staticData);
  if (blob.length > 80000) { // 80 KB hard cap
    console.log("[SAFETY] staticData too large (" + blob.length + " bytes), resetting to prevent runner crash");
    staticData.sessions = {};
    staticData.processedUpdates = {};
    delete staticData.__images;
    delete staticData.images;
  }
} catch(e) {
  staticData.sessions = {};
  staticData.processedUpdates = {};
}

// Also strip any base64 that might have slipped through from previous runs
for (const s of Object.values(staticData.sessions)) {
  if (s.currentDraft?.carouselSlides) {
    s.currentDraft.carouselSlides.forEach(slide => {
      delete slide.base64;
      delete slide.imageData;
      delete slide.svgString;
    });
  }
  delete s.currentDraft?.imageBase64;
}

// Cap processedUpdates to last 50 entries only
const puEntries = Object.entries(staticData.processedUpdates || {});
if (puEntries.length > 50) {
  const sorted = puEntries.sort((a, b) => a[1] - b[1]);
  staticData.processedUpdates = Object.fromEntries(sorted.slice(-50));
}

const session = staticData.sessions[chatId] || { state: "idle" };

// Fast help / reset commands
if (/^\/(start|help)/i.test(text)) {
  staticData.sessions[chatId] = { state: "idle" };
  return [{
    json: {
      action: "show_help",
      chatId,
      text
    }
  }];
}

if (/^\/(reset|cancel|clear)/i.test(text)) {
  staticData.sessions[chatId] = { state: "idle" };
  return [{
    json: {
      action: "reset_session",
      chatId
    }
  }];
}

// Case A: User is in "waiting_feedback" state -> feedback for current draft
if (session.state === "waiting_feedback" && session.currentDraft) {
  return [{
    json: {
      action: "apply_tweak_feedback",
      chatId,
      feedbackText: text,
      isFromVoice,
      currentDraft: session.currentDraft,
      format: session.currentDraft.format || "carousel"
    }
  }];
}

// Case B: User submitted a new post prompt
// Comprehensive detection for carousel vs single post (Turkish & English)
let detectedFormat = null;
const lower = text.toLowerCase();

// Multi-point / list / comparison / multi-page patterns -> Carousel
const isCarouselIntent = 
  lower.includes("carousel") || 
  lower.includes("kaydırmalı") || 
  lower.includes("kaydirmali") || 
  lower.includes("multi post") || 
  lower.includes("multi-post") || 
  lower.includes("slides") || 
  lower.includes("slide") || 
  lower.includes("slayt") || 
  lower.includes("çoklu sayfa") ||
  lower.includes("coklu sayfa") ||
  lower.includes("çoklu post") ||
  lower.includes("coklu post") ||
  lower.includes("her sayfa") ||
  lower.includes("her sayfada") ||
  lower.includes("karşılaştır") ||
  lower.includes("karsilastir") ||
  lower.includes("kıyas") ||
  lower.includes("kiyas") ||
  lower.includes("versus") ||
  lower.includes(" vs ") ||
  lower.includes("albüm") ||
  lower.includes("album") ||
  lower.includes("seri") ||
  /\b\d+\s*(adım|madde|yol|ipucu|taktik|öneri|fark|kural|yöntem|neden|strateji|örnek|kriter|sayfa|tane)\b/i.test(text) ||
  /\b(adımları|yolları|ipuçları|stratejileri|farkları|rehberi|dosyası|manifesto)\b/i.test(text);

const isSingleIntent = 
  lower.includes("single post") || 
  lower.includes("tek post") || 
  lower.includes("single image") || 
  lower.includes("tek görsel") || 
  lower.includes("tek fotograf") || 
  lower.includes("one post") ||
  lower.includes("tekli");

if (isCarouselIntent && !isSingleIntent) {
  detectedFormat = "carousel";
} else if (isSingleIntent && !isCarouselIntent) {
  detectedFormat = "single";
}

// If format not specified, ask user to select single vs carousel
if (!detectedFormat) {
  session.state = "waiting_format_choice";
  session.pendingTopic = text;
  session.isFromVoice = isFromVoice;
  staticData.sessions[chatId] = session;

  return [{
    json: {
      action: "ask_format_choice",
      chatId,
      topic: text,
      isFromVoice
    }
  }];
}

// Format was detected
session.state = "generating_draft";
session.format = detectedFormat;
session.topic = text;
staticData.sessions[chatId] = session;

return [{
  json: {
    action: "generate_draft",
    chatId,
    topic: text,
    format: detectedFormat,
    isFromVoice,
    feedback: null
  }
}];

// =========================================================================
// 🔘 ADVANCED CALLBACK ROUTER & MULTI-TIER SESSION RECOVERY
// =========================================================================
const item = $input.first()?.json || {};
const callbackData = String(item.callbackData || "");
const chatId = String(item.chatId || "1519369571");
const callbackId = item.callbackId;

const staticData = $getWorkflowStaticData("global");
staticData.sessions = staticData.sessions || {};
const session = staticData.sessions[chatId] || { state: "idle" };

// 1. Format Selection Callbacks (fmt_single, fmt_carousel)
if (callbackData === "fmt_single" || callbackData === "fmt_carousel") {
  const format = callbackData === "fmt_single" ? "single" : "carousel";
  const topic = session.pendingTopic || "Strategic AI & Tech Guide";

  session.state = "generating_draft";
  session.format = format;
  session.topic = topic;
  staticData.sessions[chatId] = session;

  return [{
    json: {
      action: "generate_draft",
      callbackId,
      chatId,
      topic,
      format,
      feedback: null
    }
  }];
}

// 2. User clicked "Approve & Publish to Instagram"
if (callbackData === "approve_publish" || callbackData.startsWith("approve")) {
  let currentDraft = session.currentDraft;

  // Tier 1: Check in-process global variable
  if (!currentDraft && typeof globalThis !== "undefined" && globalThis.__CODEWAFT_DRAFTS) {
    currentDraft = globalThis.__CODEWAFT_DRAFTS[chatId] || globalThis.__CODEWAFT_LAST_DRAFT;
  }

  // Tier 2: Check persistent disk backup in /tmp/
  if (!currentDraft) {
    // Disk persistence removed for sandbox compliance
  }

  // Tier 3: Check staticData.lastDraft
  if (!currentDraft && staticData.lastDraft) {
    currentDraft = staticData.lastDraft;
  }

  // Tier 4: Resilient recovery directly from Telegram message text / entities
  if (!currentDraft) {
    const rawMsg = String(item.messageText || item.messageCaption || "");
    const entities = Array.isArray(item.messageEntities) ? item.messageEntities : [];

    // Extract all image URLs from entities and regex
    const entityUrls = entities.filter(e => e.url && e.url.includes("pollinations.ai")).map(e => e.url);
    const regexUrls = [...rawMsg.matchAll(/https:\/\/gen\.pollinations\.ai\/image\/[^\s"'>]+/g)].map(m => m[0]);
    const urlMatches = Array.from(new Set([...entityUrls, ...regexUrls]));

    // Extract caption
    const capMatch = rawMsg.match(/(?:📝\s*)?(?:Instagram Metni|Instagram Açıklaması|Caption):\s*\n+([\s\S]*?)(?=\n\s*📌|\n\s*🏷️|\n\s*#|\n\s*📚|━━━━━━━━━━━━━━━━━━━━|$)/i);
    const cap = capMatch ? capMatch[1].trim() : "Codewaft Paylaşımı";

    // Extract hashtags
    const tagMatch = rawMsg.match(/(?:📌|🏷️)\s*([^\n]+)/i) || rawMsg.match(/(#[a-zA-Z0-9_]+[\s\S]*?)(?=\n|━━━━━━━━━━━━━━━━━━━━|$)/i);
    const tags = tagMatch ? tagMatch[1].trim() : "";

    if (urlMatches.length >= 2) {
      currentDraft = {
        topic: "Recovered Carousel",
        format: "carousel",
        theme: { style: "The Editorial Field Guide", categoryTag: "STRATEGIC GUIDE" },
        caption: cap,
        hashtags: tags,
        imageUrl: urlMatches[0],
        carouselSlides: urlMatches.map((url, idx) => ({
          slide: idx + 1,
          title: `Slide ${idx + 1}`,
          imageUrl: url
        })),
        iterationCount: 1
      };
    } else if (urlMatches.length === 1) {
      currentDraft = {
        topic: "Recovered Single Post",
        format: "single",
        theme: { style: "The Editorial Field Guide", categoryTag: "STRATEGIC GUIDE" },
        caption: cap,
        hashtags: tags,
        imageUrl: urlMatches[0],
        carouselSlides: [],
        iterationCount: 1
      };
    }
  }

  if (!currentDraft) {
    return [{
      json: {
        action: "error_no_draft",
        callbackId,
        chatId,
        errorMessage: "No active draft found. Please send a new idea to create a fresh draft!"
      }
    }];
  }

  return [{
    json: {
      action: "publish_instagram",
      callbackId,
      chatId,
      draft: currentDraft
    }
  }];
}

// 3. User clicked "Request Tweaks"
if (callbackData === "tweak_post" || callbackData.startsWith("tweak")) {
  session.state = "waiting_feedback";
  staticData.sessions[chatId] = session;

  return [{
    json: {
      action: "prompt_for_tweaks",
      callbackId,
      chatId
    }
  }];
}

// 4. User clicked "Start from Zero"
if (callbackData === "reset_post" || callbackData.startsWith("reset")) {
  staticData.sessions[chatId] = { state: "idle" };
  staticData.lastDraft = null;
  if (typeof globalThis !== "undefined" && globalThis.__CODEWAFT_DRAFTS) delete globalThis.__CODEWAFT_DRAFTS[chatId];
  // Disk persistence removed for sandbox compliance
  return [{
    json: {
      action: "start_from_zero",
      callbackId,
      chatId
    }
  }];
}

// 5. User clicked "Cancel"
if (callbackData === "cancel_draft" || callbackData.startsWith("cancel")) {
  staticData.sessions[chatId] = { state: "idle" };
  staticData.lastDraft = null;
  if (typeof globalThis !== "undefined" && globalThis.__CODEWAFT_DRAFTS) delete globalThis.__CODEWAFT_DRAFTS[chatId];
  // Disk persistence removed for sandbox compliance
  return [{
    json: {
      action: "cancel_draft",
      callbackId,
      chatId
    }
  }];
}

return [{
  json: {
    action: "unknown_callback",
    callbackId,
    chatId
  }
}];

// =========================================================================
// 🎨 PREPARE AI PROMPT (ENGLISH PROMPT ENGINE & FLUX FIDELITY SPECIALIST)
// =========================================================================
// Telegram sendMessage returns a message receipt, not the original topic.
// Recover generation context from the branch that ran in this execution.
let input = $input.first()?.json || {};
if (!input.topic && !input.feedbackText && !input.currentDraft) {
  for (const nodeName of ["Evaluate Text Intent", "Handle Callback Query"]) {
    try {
      const source = $(nodeName).first()?.json;
      if (source && (source.topic || source.feedbackText || source.currentDraft)) {
        input = source;
        break;
      }
    } catch (_) { /* The other branch did not execute. */ }
  }
}
const chatId = String(input.chatId || "1519369571");
let topic = String(input.topic || input.feedbackText || "").trim();
let format = input.format || "carousel";

if (!topic && input.currentDraft) {
  topic = input.currentDraft.topic;
  format = input.currentDraft?.format || "carousel";
}

const feedback = input.feedbackText || null;
const currentDraft = input.currentDraft || null;

// Determine target slide count based on user topic (e.g. 3 pages / 5 tips)
let targetSlideCount = format === "carousel" ? 3 : 1;
const numMatch = topic.match(/\b(\d+)\s*(adım|madde|yol|ipucu|taktik|öneri|fark|kural|yöntem|neden|strateji|örnek|kriter|sayfa|tane|page|slide|point|step|tip|way)\b/i);
if (format === "carousel" && numMatch) {
  const n = parseInt(numMatch[1], 10);
  if (n >= 2 && n <= 7) targetSlideCount = n;
}

const systemLines = [
  "You are an elite Senior Social Media Copywriter, Editorial Publication Designer, and Quality Assurance Proofreader for @developmentserhat.",
  "Your mission is to produce world-class, intellectually stimulating, grammatically flawless, and visually impeccable Instagram publications in ENGLISH.",
  "",
  "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━",
  "🌍 MANDATORY ENGLISH LANGUAGE DIRECTIVE:",
  "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━",
  "1. CRITICAL: EVEN IF THE USER INPUT OR TOPIC IS GIVEN IN TURKISH OR ANY OTHER LANGUAGE, YOU MUST COMPOSE AND OUTPUT 100% OF THE CONTENT IN ENGLISH:",
  "   - All visual text on graphics (Category Eyebrows, Main Headlines, Takeaway Cards) MUST BE IN ENGLISH.",
  "   - All AI visual generation prompts (slidePrompt, imagePrompt) MUST BE IN DETAILED, HIGH-FIDELITY ENGLISH for Flux 1 Schnell.",
  "   - The entire Instagram caption, key takeaways, calls-to-action, and hashtags MUST BE IN ENGLISH.",
  "   - All theme and design descriptions MUST BE IN ENGLISH.",
  "2. WHY THIS MATTERS FOR IMAGE GENERATION:",
  "   - AI image generation models (Flux 1 Schnell) achieve maximum fidelity, razor-sharp typography, and zero character-garbling when generating English letters.",
  "",
  "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━",
  "🛡️ MANDATORY QUALITY ASSURANCE & TEXT ACCURACY DIRECTIVES:",
  "━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━",
  "1. TEXT FIDELITY ON GRAPHIC IMAGES:",
  "   - Keep all visual text on the graphic cards SHORT, PUNCHY, and CAPITALIZED:",
  "     • Category Eyebrows: Exactly 1 to 2 words in uppercase (e.g. 'AI COMPARISON', 'BENCHMARK', 'KEY VERDICT').",
  "     • Main Headline on Graphic: Exactly 3 to 5 words maximum in double quotes (e.g. 'CLAUDE VS GEMINI VS GPT').",
  "     • Takeaway Cards on Graphic: Exactly 2 to 4 words per card title (e.g. '01 · REASONING & CODING', '02 · CONTEXT & SPEED').",
